'use client'

/**
 * TreeLogoMark — the animated tree mark, drawn on from the base outward.
 *
 * The geometry is the real extracted logo (41 variable-width strokes with the
 * original taper, 27 leaves), so this component and the rendered MP4 match.
 * A single rAF loop advances a 0..1 timeline; each stroke is emitted as a
 * partial ribbon polygon — the same algorithm the Python renderer uses — which
 * gives the authentic variable-width pen-draw.
 *
 * `animate={false}` renders the finished static mark (favicons, print,
 * prefers-reduced-motion).
 */
