const clamp = (v: number) => (v < 0 ? 0 : v > 1 ? 1 : v)
const smooth = (t: number, a: number, b: number) => {
  if (b <= a) return 0
  const x = clamp((t - a) / (b - a))
  return x * x * (3 - 2 * x)
}
const easeOut = (t: number, k = 2.4) => 1 - Math.pow(1 - clamp(t), k)

/** The stroke revealed up to `reveal` of its arc length, as a ribbon polygon. */
function ribbonPath(pts: Pt[], ws: number[], reveal: number): string {
  const n = pts.length
  if (n < 2) return ""
  const segs: number[] = []
  for (let i = 0; i < n - 1; i++) {
    segs.push(Math.hypot(pts[i + 1][0] - pts[i][0], pts[i + 1][1] - pts[i][1]))
  }
  const total = segs.reduce((a, b) => a + b, 0)
  const target = total * clamp(reveal)

  const cum = [0]
  for (const s of segs) cum.push(cum[cum.length - 1] + s)
  const keep = target >= cum[cum.length - 1] ? n : cum.findIndex((c) => c >= target) + 1
  if (keep < 2) return ""

  const left: Pt[] = []
  const right: Pt[] = []
  for (let i = 0; i < keep; i++) {
    let dx: number, dy: number
    if (i === 0) {
      dx = pts[1][0] - pts[0][0]
      dy = pts[1][1] - pts[0][1]
    } else if (i === keep - 1) {
      dx = pts[keep - 1][0] - pts[keep - 2][0]
      dy = pts[keep - 1][1] - pts[keep - 2][1]
    } else {
      dx = pts[i + 1][0] - pts[i - 1][0]
      dy = pts[i + 1][1] - pts[i - 1][1]
    }
    const m = Math.hypot(dx, dy) || 1
    const nx = -dy / m
    const ny = dx / m
    const hw = ws[i] / 2
    left.push([pts[i][0] + nx * hw, pts[i][1] + ny * hw])
    right.push([pts[i][0] - nx * hw, pts[i][1] - ny * hw])
  }

  const p0: Pt = [pts[0][0], pts[0][1]]
  const p1: Pt = [pts[keep - 1][0], pts[keep - 1][1]]
  const r0 = ws[0] / 2
  const r1 = ws[keep - 1] / 2

  const f = (p: Pt) => `${p[0].toFixed(2)} ${p[1].toFixed(2)}`
  return (
    "M " + left.map(f).join(" L ") +
    " L " + right.reverse().map(f).join(" L ") +
    // round caps, mirroring the Python renderer
    ` A ${r1.toFixed(2)} ${r1.toFixed(2)} 0 0 1 ${f(p1)}` +
    ` A ${r0.toFixed(2)} ${r0.toFixed(2)} 0 0 1 ${f(p0)} Z`
  )
}

/** Leaf anchor = first point of its path (the base tip), for scaling about it. */
function leafAnchor(d: string): Pt {
  const m = /^M\s+(-?[\d.]+)\s+(-?[\d.]+)/.exec(d)
  return m ? [+m[1], +m[2]] : [0, 0]
}

export function TreeLogoMark({
  className,
  animate = true,
  title,
  ink = INK,
  leaf = LEAF,
}: {
  className?: string
  animate?: boolean
  title?: string
  /** Stroke colour. Override to white when the mark sits on a dark surface. */
  ink?: string
  /** Leaf colour. Override to a token when the mark sits on a dark surface. */
  leaf?: string
}) {
  const [t, setT] = useState(1)

  useEffect(() => {
    if (!animate) {
      setT(1)
      return
    }
    if (typeof window !== "undefined" &&
        window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      setT(1)
      return
    }
    let raf = 0
    const start = performance.now()
    const tick = (now: number) => {
      const p = clamp((now - start) / DURATION)
      setT(p)
      if (p < 1) raf = requestAnimationFrame(tick)
    }
    raf = requestAnimationFrame(tick)
    return () => cancelAnimationFrame(raf)
  }, [animate])

  return (
    <svg
      viewBox="0 0 400 400"
      role={title ? "img" : "presentation"}
      aria-label={title}
      className={cn("overflow-visible", className)}
    >
      <g fill={ink}>
        {SCHED.map(([bi, a, b]) => {
          const r = smooth(t, a, b)
          if (r <= 0) return null
          const s = STROKES[bi]
          const d = ribbonPath(s.p, s.w, r)
          return d ? <path key={bi} d={d} /> : null
        })}
      </g>

      <g fill={leaf}>
        {LEAF_SCHED.map(([bi, a, b]) => {
          const r = smooth(t, a, b)
          if (r <= 0) return null
          const scale = easeOut(r)
          const [cx, cy] = leafAnchor(LEAVES[bi])
          return (
            <path
              key={bi}
              d={LEAVES[bi]}
              opacity={clamp(r * 1.6)}
              transform={`translate(${cx} ${cy}) scale(${scale.toFixed(3)}) translate(${-cx} ${-cy})`}
            />
          )
        })}
      </g>
    </svg>
  )
}

export function TreeLogoLockup({
  className,
  animate = true,
  title = "Recovery Journey",
  markClassName,
  wordmark = "RECOVERY JOURNEY",
  size = "md",
}: {
  className?: string
  animate?: boolean
  title?: string
  markClassName?: string
  /** Override the wordmark text; pass null to render the mark alone. */
  wordmark?: string | null
  size?: "sm" | "md" | "lg"
}) {
  const markSize = { sm: "max-w-[120px]", md: "max-w-[190px]", lg: "max-w-[260px]" }[size]
  const textSize = { sm: "text-[10px]", md: "text-sm", lg: "text-base" }[size]
  return (
    <div className={cn("flex flex-col items-center", className)}>
      <TreeLogoMark
        className={cn("w-full", markSize, markClassName)}
        animate={animate}
        title={title}
      />
      {wordmark && (
        <div
          className={cn("mt-2 text-center text-[#444D47]", textSize)}
          style={{ fontFamily: "Georgia, 'Times New Roman', serif" }}
        >
          <div className="tracking-[0.22em]">{wordmark}</div>
        </div>
      )}
    </div>
  )
}